- tools=Noneの既存パス(非破壊)
- tools付与時のツール呼び出しループ(python_repl実行→再呼び出し→最終応答)
- json_mode無効化(response_formatが渡されないこと)
- MAX_TOOL_ITER非収束時のRuntimeError伝播(D-009)
を検証する。cela.dbは作らない(query_AI/_query_AI_liveはDBを触らない)。
"""
import json
import sys

sys.path.insert(0, r"c:\ai_work\CELA")
import cela_main as m


class FakeFunction:
    def __init__(self, name, arguments):
        self.name = name
        self.arguments = arguments


class FakeToolCall:
    def __init__(self, id_, name, arguments):
        self.id = id_
        self.function = FakeFunction(name, arguments)


class FakeMessage:
    def __init__(self, content=None, tool_calls=None):
        self.content = content
        self.tool_calls = tool_calls

    def model_dump(self):
        return {
            "role": "assistant",
            "content": self.content,
            "tool_calls": [
                {"id": tc.id, "type": "function",
                 "function": {"name": tc.function.name, "arguments": tc.function.arguments}}
                for tc in (self.tool_calls or [])
            ] or None,
        }


class FakeChoice:
    def __init__(self, message, finish_reason):
        self.message = message
        self.finish_reason = finish_reason


class FakeResponse:
    def __init__(self, message, finish_reason="stop"):
        self.choices = [FakeChoice(message, finish_reason)]


class FakeClient:
    """scripted_responses: list of callables(create_kwargs) -> FakeResponse, consumed in order."""

    def __init__(self, scripted_responses):
        self.scripted_responses = list(scripted_responses)
        self.calls = []
        self.base_url = "https://fake.local/v1"

        class _Completions:
            def create(inner_self, **kwargs):
                self.calls.append(kwargs)
                if not self.scripted_responses:
                    raise AssertionError("フェイククライアントの応答スクリプトが尽きました")
                return self.scripted_responses.pop(0)(kwargs)

        class _Chat:
            completions = _Completions()

        self.chat = _Chat()


def reset():
    m.REPLAY_MODE = "off"
    m.reset_call_seq()


def test_1_non_tool_path_unchanged():
    reset()
    client = FakeClient([lambda kw: FakeResponse(FakeMessage(content="hello"), finish_reason="stop")])
    result = m.query_AI([{"role": "user", "content": "hi"}], client=client, model="fake", label="Expert:test")
    assert result == "hello", result
    assert "tools" not in client.calls[0]
    print("OK 1: tools=Noneの既存パスは維持されている")


def test_2_tool_loop_executes_python_repl_and_returns_final_answer():
    reset()

    def round1(kw):
        assert kw.get("tools") is not None, "toolsが渡されていない"
        assert "response_format" not in kw, "tools付与時はresponse_formatを指定してはいけない(D-005/設計書3.5.1)"
        tc = FakeToolCall("call_1", "python_repl", json.dumps({"code": "print(2500+300+800)"}))
        return FakeResponse(FakeMessage(content=None, tool_calls=[tc]), finish_reason="tool_calls")

    def round2(kw):
        # 直前のtool結果がmessagesに正しく積まれているか確認
        last_msgs = kw["messages"]
        assert last_msgs[-1]["role"] == "tool"
        assert "3600" in last_msgs[-1]["content"]
        return FakeResponse(FakeMessage(content="矛盾を検出しました。合計は3600万円です。"), finish_reason="stop")

    client = FakeClient([round1, round2])
    result = m.query_AI(
        [{"role": "user", "content": "検算して"}], client=client, model="fake",
        label="Detector", tools=[m.PYTHON_REPL_TOOL],
    )
    assert "3600" in result, result
    assert len(client.calls) == 2
    print("OK 2: ツール呼び出しループが正常に往復し、最終応答を返した")


def test_3_broken_tool_args_json_self_heals():
    reset()

    def round1(kw):
        tc = FakeToolCall("call_1", "python_repl", "{not valid json")
        return FakeResponse(FakeMessage(content=None, tool_calls=[tc]), finish_reason="tool_calls")

    def round2(kw):
        last_msg = kw["messages"][-1]
        assert last_msg["role"] == "tool"
        payload = json.loads(last_msg["content"])
        assert "error" in payload, "壊れたJSON引数はエラーとしてモデルに返されるべき(D-009)"
        return FakeResponse(FakeMessage(content="修正して再試行しました"), finish_reason="stop")

    client = FakeClient([round1, round2])
    result = m.query_AI(
        [{"role": "user", "content": "検算して"}], client=client, model="fake",
        label="Reviewer QA", tools=[m.PYTHON_REPL_TOOL],
    )
    assert result == "修正して再試行しました"
    print("OK 3: 壊れたtool_call引数JSONはRuntimeErrorにせず自己修復ループに回された")


def test_4_non_convergence_raises_runtime_error():
    reset()

    def always_tool_call(kw):
        tc = FakeToolCall("call_x", "python_repl", json.dumps({"code": "print(1)"}))
        return FakeResponse(FakeMessage(content=None, tool_calls=[tc]), finish_reason="tool_calls")

    client = FakeClient([always_tool_call] * 5)
    try:
        m.query_AI(
            [{"role": "user", "content": "検算して"}], client=client, model="fake",
            label="Detector", tools=[m.PYTHON_REPL_TOOL],
        )
        raise AssertionError("RuntimeErrorが発生するべきでした")
    except RuntimeError as e:
        assert "収束しませんでした" in str(e)
        print(f"OK 4: MAX_TOOL_ITER非収束でRuntimeErrorが正しく伝播した: {e}")


def test_5_length_finish_reason_raises_value_error_in_tool_loop():
    reset()

    def truncated(kw):
        return FakeResponse(FakeMessage(content=None, tool_calls=None), finish_reason="length")

    client = FakeClient([truncated])
    try:
        m.query_AI(
            [{"role": "user", "content": "検算して"}], client=client, model="fake",
            label="Detector", tools=[m.PYTHON_REPL_TOOL],
        )
        raise AssertionError("ValueErrorが発生するべきでした")
    except ValueError as e:
        assert "truncated" in str(e)
        print(f"OK 5: finish_reason=lengthがツールループ内でも検出された(D-009): {e}")


if __name__ == "__main__":
    test_1_non_tool_path_unchanged()
    test_2_tool_loop_executes_python_repl_and_returns_final_answer()
    test_3_broken_tool_args_json_self_heals()
    test_4_non_convergence_raises_runtime_error()
    test_5_length_finish_reason_raises_value_error_in_tool_loop()
    print("\nALL SMOKE TESTS PASSED")

